1	type Cell = [number, number]; // [x, y]
2	
3	function isNeighbor([x, y]: Cell, [otherX, otherY]: Cell): boolean {
4	  const isSameCell = x === otherX && y === otherY;
5	  return !isSameCell && Math.abs(otherX - x) <= 1 && Math.abs(otherY - y) <= 1;
6	}
7	
8	function countLiveNeighbors(cell: Cell, liveCells: Cell[]): number {
9	  return liveCells.filter((other) => isNeighbor(cell, other)).length;
10	}
11	
12	export function nextGeneration(liveCells: Cell[]): Cell[] {
13	  return liveCells.filter((cell) => {
14	    const liveNeighbors = countLiveNeighbors(cell, liveCells);
15	    return liveNeighbors === 2 || liveNeighbors === 3;
16	  });
17	}
